cs-0050 | agent:run-231 | tệp ×1 | Kích hoạt bọc DSI và chân reset PH7 ngay sau khi khởi tạo màn hình xong.

diff --git a/firmware/stm32469i_discovery_lcd.c b/firmware/stm32469i_discovery_lcd.c
index 73302bb..83a81c2 100644
--- a/firmware/stm32469i_discovery_lcd.c
+++ b/firmware/stm32469i_discovery_lcd.c
@@ -420,6 +420,12 @@ uint8_t BSP_LCD_InitEx(LCD_OrientationTypeDef orientation)
     return LCD_ERROR;
   }

+  /* Dam bao Wrapper DSI bat, SHTDN tat, PH7 cao */
+  DSI->WCR &= ~DSI_WCR_SHTDN;
+  DSI->WCR |= DSI_WCR_DSIEN;
+  __HAL_DSI_WRAPPER_ENABLE(&hdsi_eval);
+  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
+
   return LCD_OK;
 }

